body.raw:
{
  "config": {
    "schemaVersion": 1,
    "game_id": "{{gameId}}",
    "theme": {
      "mode": "light",
      "fonts": {
        "heading": {
          "family": "Fredoka",
          "source": "google"
        },
        "body": {
          "family": "Nunito",
          "source": "google"
        }
      },
      "frame": {
        "style": "none",
        "width": 1,
        "color": "#D9DBD5",
        "corners": "round"
      },
      "buttons": {
        "style": "outline",
        "case": "normal"
      },
      "panel": {
        "opacity": 0.9,
        "blur": true
      },
      "colors": {
        "brand": "#2E8B57",
        "background": "#FFFFFF",
        "surface": "#F2F3F1",
        "text": "#000000",
        "muted": "#5B5D56"
      },
      "textures": {}
    },
    "layout": {
      "position": "bottom-left",
      "startCollapsed": false
    },
    "friends": {
      "enabled": true
    },
    "clan": {
      "enabled": true,
      "maxMembers": 10,
      "descriptionMax": 140,
      "roles": [
        {
          "id": "member",
          "name": "Member",
          "canPromote": false,
          "canKick": false
        },
        {
          "id": "leader",
          "name": "Leader",
          "canPromote": true,
          "canKick": true
        }
      ],
      "badges": {
        "source": "developer",
        "allowed": []
      },
      "screens": {
        "discover": {
          "enabled": false
        },
        "create": {
          "enabled": false
        },
        "home": {
          "enabled": false,
          "header": "compact",
          "showStats": false
        },
        "members": {
          "enabled": false
        }
      }
    },
    "chat": {
      "enabled": true,
      "layout": "bubbles",
      "directMessages": true,
      "clanChat": true,
      "maxMessageLength": 500,
      "slowModeSeconds": 0,
      "profanityFilter": false,
      "historyLimit": 50
    },
    "texts": {
      "terms": {
        "clan": "Clan",
        "clans": "Clans"
      },
      "labels": {}
    }
  }
}
